insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('1b336385-f4d1-4f4c-af28-d632ba3ce90c', '881307d4-97f4-4979-ad9d-f9eb03d851ab', $$figuur 1 — (U,I)-karakteristieken van LED’s met verschillende kleuren$$,
   $$natuurkunde-vwo-2016-i-gekleurde-leds-context1.png$$,
   $$Een LED (Light Emitting Diode) is een diode die licht uitzendt als deze in de doorlaatrichting geschakeld is. In figuur 1 staan de (U,I)-karakteristieken van een aantal LED’s met verschillende kleuren.

figuur 1: (U,I)-diagram met op de verticale as de spanning U (in V, 0 tot 1,90) en op de horizontale as de stroomsterkte I (in mA, 0 tot 2,0); drie stijgende krommen voor rood, geel en groen, waarbij de rode LED bij elke stroomsterkte de laagste spanning heeft en de groene LED de hoogste.$$, 'inline'),
  ('e6236d9e-f770-47b7-bc68-54503f0acda3', '881307d4-97f4-4979-ad9d-f9eb03d851ab', $$figuur 2 — rode LED in serie met weerstand R, U=3,00 V, I=0,60 mA$$,
   $$natuurkunde-vwo-2016-i-gekleurde-leds-context2.png$$,
   $$In figuur 2 is een schakeling getekend waarin een rode LED in serie geschakeld is met een weerstand.
De spanning U = 3,00 V.
Door de rode LED in figuur 2 loopt een stroomsterkte van 0,60 mA.

figuur 2: schakelschema met een spanningsbron U = 3,00 V in serie met een weerstand R en een LED.$$, 'inline'),
  ('c784eed6-3b58-4f92-9609-3532e57abba6', '881307d4-97f4-4979-ad9d-f9eb03d851ab', $$figuur 3 — bouw van een LED, materialen A en B met verschillend energieniveau$$,
   $$natuurkunde-vwo-2016-i-gekleurde-leds-context3.png$$,
   $$In figuur 3 is de bouw van een LED vereenvoudigd weergegeven.
Een LED is opgebouwd uit twee materialen, A en B.
In de materialen A en B hebben de geleidings-elektronen een verschillend energieniveau. De keuze voor de materialen A en B bepaalt de kleur van het licht dat de LED uitzendt.

figuur 3: schakeling met een spanningsbron U aangesloten op een LED die is opgebouwd uit twee tegen elkaar geplaatste materialen A en B.$$, 'inline'),
  ('e20bbdff-002e-4d4c-82aa-1c149a0ff94b', '881307d4-97f4-4979-ad9d-f9eb03d851ab', $$figuur 4 — vier schema’s (I t/m IV) met energieniveaus van de geleidings-elektronen$$,
   $$natuurkunde-vwo-2016-i-gekleurde-leds-context4.png$$,
   $$In figuur 4 staan vier schema’s met energieniveaus van de geleidings-elektronen weergegeven.

figuur 4: vier energieniveauschema’s (I, II, III, IV) met de energieniveaus van materiaal A en materiaal B en een pijl die de overgang van een geleidingselektron tussen beide niveaus aangeeft; in de schema’s verschilt zowel de richting van de pijl (van A naar B of van B naar A) als welk niveau (A of B) het hoogste energieniveau heeft.$$, 'inline'),
  ('3b9d62f5-3c7b-4ffe-8986-373e9230f6d2', 'b3036490-a9e6-4980-9ceb-9d69f5241adf', $$Ruimtelift? — artikel over haalbaarheidsstudie ruimtelift TU Delft/ESA$$,
   $$natuurkunde-vwo-2016-i-ruimtelift-context1.png$$,
   $$Lees onderstaand artikel.

Ruimtelift?
Wetenschappers van de TU-Delft en ESA (European Space Agency) in Noordwijk hebben modelstudies uitgevoerd naar de haalbaarheid van een zogenaamde Ruimtelift naar geostationaire satellieten.
Geostationaire satellieten bevinden zich namelijk op een vaste plaats boven de evenaar vanaf de aarde gezien. Een kabel tussen de aarde en een geostationaire satelliet kan niet, omdat de satelliet dan door de kabel naar beneden getrokken wordt. Maar zou een langere kabel met een contragewicht wel kunnen?
Hierover gaat de haalbaarheidsstudie naar de ‘ruimtelift’: langs een lange kabel duizenden kilometers omhoog klimmen. Wat je nodig hebt is een strakke kabel en een slimme manier van klimmen.

figuur: artist’s impression van de aarde met een lange kabel (‘space elevator’) die van het aardoppervlak omhoog de ruimte in loopt.$$, 'inline'),
  ('a5f65e4f-5d7c-4ac4-a74f-43f1e177441a', 'b3036490-a9e6-4980-9ceb-9d69f5241adf', $$figuur 1 — gravitatiekracht Fg en middelpuntzoekende kracht Fmpz tegen hoogte h$$,
   $$natuurkunde-vwo-2016-i-ruimtelift-context2.png$$,
   $$kabel
In figuur 1 is de gravitatiekracht op een voorwerp als functie van de hoogte boven het aardoppervlak weergegeven. Ook is de middelpuntzoekende kracht weergegeven die nodig is voor dat voorwerp als het beweegt met dezelfde omlooptijd als de aarde.

figuur 1: (F,h)-diagram met op de verticale as de kracht F (in N) en op de horizontale as de hoogte h (in m); de dalende kromme Fg (gravitatiekracht) en de stijgende kromme Fmpz (middelpuntzoekende kracht) snijden elkaar bij de geostationaire hoogte.$$, 'inline'),
  ('a63bb819-b95c-480c-9c5c-d5151af85bd0', 'b3036490-a9e6-4980-9ceb-9d69f5241adf', $$figuur 2 — massa B aan lange kabel die met de aarde meedraait$$,
   $$natuurkunde-vwo-2016-i-ruimtelift-context3.png$$,
   $$De modelstudie gaat uit van een kabel, die veel langer is dan de geostationaire hoogte, met daaraan een grote massa B die met de aarde meedraait. Zie figuur 2.
In dat geval staat de kabel strak gespannen.

figuur 2: de aarde met daarvandaan een horizontale kabel tot aan de geostationaire hoogte en verder naar een grote massa B ver daarbuiten.$$, 'inline'),
  ('2483a1f4-9e36-4551-bedd-4eea04b1a84a', 'b3036490-a9e6-4980-9ceb-9d69f5241adf', $$figuur 3 — modelregels (tekstmodel) en grafisch model van de klimmende lift$$,
   $$natuurkunde-vwo-2016-i-ruimtelift-context4.png$$,
   $$klimmen
Vervolgens hebben de wetenschappers een modelstudie gedaan naar de lift die langs de kabel naar boven zal gaan.
Hierbij is de lift voorzien van een brandstofmotor.
Het model berekent de massa van de aanwezige brandstof als functie van de hoogte, als de lift met constante snelheid omhoog beweegt.
Het model staat als tekstmodel en als grafisch model weergegeven in figuur 3 en op de uitwerkbijlage. Je kunt zelf kiezen welke je gebruikt.

figuur 3: modelregels 1 t/m 12 (tekstmodel) met bijbehorende startwaarden in SI-eenheden (rx=Ra+x, mtot=m_lift+m_brandstof, Fg=G·Ma·mtot/rx², Fmpz=mtot·4π²·rx/(24·3600)², Fmotor=Fg−Fmpz, dx=v·dt, x=x+dx, dW=Fmotor·dx, dm_brandstof=…, m_brandstof=m_brandstof−dm_brandstof, als x>4,0·10⁷ dan stop, t=t+dt), en daaronder hetzelfde model als grafisch (stroom)diagram met pijlen tussen de grootheden, waarbij pijl I overeenkomt met modelregel 8 (dW) en pijl II met modelregel 9 (dm_brandstof).$$, 'inline'),
  ('380aa9f9-0064-4d88-886d-56eff18db5bd', 'b3036490-a9e6-4980-9ceb-9d69f5241adf', $$figuur 4 — massa brandstof tegen hoogte, voor start met 10·10³ kg en 5,0·10³ kg$$,
   $$natuurkunde-vwo-2016-i-ruimtelift-context5.png$$,
   $$De resultaten van het model staan weergegeven in figuur 4 als de lift begint met 10·10³ kg brandstof (gestippelde lijn) en met 5,0·10³ kg brandstof (getrokken lijn). Je ziet dat bij de lift die begint met 10·10³ kg brandstof op het eind 1,2·10³ kg brandstof over is en dus 8,8·10³ kg verbruikt is.

figuur 4: grafiek van de massa brandstof m_brandstof (in ·10³ kg, 0 tot 10) tegen de hoogte h (in ·10³ km, 0 tot 40); de gestippelde lijn (start 10·10³ kg) eindigt bij ongeveer 1,2·10³ kg, de getrokken lijn (start 5,0·10³ kg) daalt sneller naar bijna 0.$$, 'inline'),
  ('bfe11062-422b-4f38-9d46-0c09e593a360', 'b3036490-a9e6-4980-9ceb-9d69f5241adf', $$figuur 5 (intro) — lift met toenemende snelheid, massa 6,0·10³ kg na 1,0 dag$$,
   $$natuurkunde-vwo-2016-i-ruimtelift-context6.png$$,
   $$Het model gaat uit van een lift met constante snelheid. In werkelijkheid kan dat niet.
Volgens een ander model start de lift met voldoende brandstof vanuit stilstand en neemt de snelheid toe zoals weergegeven in figuur 5. Na 1,0 dag is de massa van de lift met brandstof gelijk aan 6,0·10³ kg.
Figuur 5 staat vergroot weergegeven op de uitwerkbijlage.

figuur 5: (v,t)-diagram met op de verticale as de snelheid v (in m s⁻¹, 0 tot 18) en op de horizontale as de tijd t (in dag, 0 tot 2,0); v stijgt snel vanuit 0 en vervolgens geleidelijker verder.$$, 'inline'),
  ('39454ab0-4e0a-47c7-8e6e-626fb6a50697', 'b3036490-a9e6-4980-9ceb-9d69f5241adf', $$uitwerkbijlage vraag 7 — modelregels en grafisch model om modelregel 9/formule II aan te vullen$$,
   $$natuurkunde-vwo-2016-i-ruimtelift-context7.png$$,
   $$uitwerkbijlage bij vraag 7: dezelfde modelregels (tekstmodel) met startwaarden en hetzelfde grafisch model als in figuur 3, met bij modelregel 9 een open plek (………) en bij pijl II in het grafisch model een leeg vak, zodat de leerling modelregel 9 / formule II kan aanvullen.$$, 'uitwerkbijlage'),
  ('1d17d7b0-9496-497b-8e72-2526951fa53e', 'b3036490-a9e6-4980-9ceb-9d69f5241adf', $$uitwerkbijlage vraag 9 — figuur 5 vergroot ((v,t)-diagram)$$,
   $$natuurkunde-vwo-2016-i-ruimtelift-context8.png$$,
   $$uitwerkbijlage bij vraag 9: figuur 5 vergroot weergegeven ((v,t)-diagram van de lift die vanuit stilstand met toenemende snelheid omhoog beweegt), zodat de leerling hierin de helling op t = 1,0 dag kan bepalen.$$, 'uitwerkbijlage'),
  ('3038894d-736f-4f11-b9ac-0319d15c9e3c', 'b3036490-a9e6-4980-9ceb-9d69f5241adf', $$uitwerkbijlage vraag 10 — figuur 5 vergroot, tweede exemplaar$$,
   $$natuurkunde-vwo-2016-i-ruimtelift-context9.png$$,
   $$uitwerkbijlage bij vraag 10: een tweede, identiek exemplaar van figuur 5 vergroot weergegeven ((v,t)-diagram), zodat de leerling hierin de oppervlakte onder de grafiek tot t = 1,0 dag kan bepalen.$$, 'uitwerkbijlage'),
  ('2f43412a-d451-4204-9a63-78350bff5c0f', '8f465511-2414-40b9-ad7c-c3de982225a6', $$figuur 1 — slaggrootte d en horizontale afstand x van de vleugeltip$$,
   $$natuurkunde-vwo-2016-i-vliegen-context1.png$$,
   $$Vogels en vleermuizen, maar ook insecten, bewegen zich voort door hun vleugels op en neer te bewegen. De verticale afstand tussen de uiterste standen van de vleugeltippen noemen we de slaggrootte d. De afstand die horizontaal bij een volledige op- en neergaande beweging wordt afgelegd, noemen we x. In figuur 1 zijn deze grootheden aangegeven.

figuur 1: drie standen van een vliegend dier (hoogste, middelste en laagste vleugelstand) met daarbij de verticale slaggrootte d en de horizontaal afgelegde afstand x tijdens één volledige op- en neergaande vleugelslag.$$, 'inline'),
  ('b2aa6ba0-815e-4c2a-92bf-d113e27be5f0', '8f465511-2414-40b9-ad7c-c3de982225a6', $$getal van Strouhal St=d/x, voor vliegende dieren geldt St=0,30 (dimensieloos)$$,
   $$natuurkunde-vwo-2016-i-vliegen-context2.png$$,
   $$De verhouding d/x wordt het getal van Strouhal (St) genoemd.
Uit biomechanisch onderzoek blijkt dat voor zeer uiteenlopende vliegende dieren geldt: St = 0,30. Het getal van Strouhal is een voorbeeld van een dimensieloze grootheid. Een dimensieloze grootheid heeft geen eenheid.$$, 'inline'),
  ('d07f5810-754c-43c5-9759-83d0aa1ee773', '8f465511-2414-40b9-ad7c-c3de982225a6', $$formule (1): St=f·d/v — getal van Strouhal uit slagfrequentie, slaggrootte en vliegsnelheid$$,
   $$natuurkunde-vwo-2016-i-vliegen-context3.png$$,
   $$Het getal van Strouhal kan in de praktijk berekend worden met:
St = f·d / v   (1)
Hierin is:
− St het getal van Strouhal;
− f de slagfrequentie in Hz;
− d de slaggrootte in m;
− v de vliegsnelheid in m s⁻¹.$$, 'inline'),
  ('8a886dce-aa63-4809-8afb-7bbd7f8da769', '8f465511-2414-40b9-ad7c-c3de982225a6', $$figuur 2a/b/c — foto’s van een zilvermeeuw in hoogste, evenwichts- en laagste vleugelstand$$,
   $$natuurkunde-vwo-2016-i-vliegen-context4.png$$,
   $$Het is mogelijk om uit enkele foto’s van een vogel in de lucht zijn snelheid te bepalen.
Figuren 2a, b en c zijn opnames van een zilvermeeuw met de vleugels in de hoogste stand, de evenwichtsstand en de laagste stand van één slagbeweging. De opnames hebben dezelfde schaal en zijn met een tussentijd van 40 ms gemaakt. De spanwijdte is 1,4 m.

figuur 2a/2b/2c: drie zwart-witfoto’s van dezelfde zilvermeeuw in vlucht, op dezelfde schaal, met de vleugels achtereenvolgens in de hoogste stand, de evenwichtsstand en de laagste stand.$$, 'inline'),
  ('b23d80cd-ee19-42e8-bf4b-d21a3f2b5ff5', '8f465511-2414-40b9-ad7c-c3de982225a6', $$figuur 3 — verticale uitwijking u van vleugeltip vogel 1 tegen x, met lijn OA (steilheid=St)$$,
   $$natuurkunde-vwo-2016-i-vliegen-context5.png$$,
   $$De vliegbeweging van twee verschillende vogels wordt vergeleken. Beide vogels hebben bij x = 0 m de vleugeltip in de laagste stand.
In figuur 3 is de verticale uitwijking van de vleugeltip van vogel 1 als functie van de horizontale afstand x weergegeven. In de figuur is tussen de oorsprong (O) en de hoogste vleugelstand (A) een rechte stippellijn getrokken.
Vogel 1 bereikt zijn uiterste vleugelstand (A) bij x = 0,50 m.
Vogel 2 is groter en bereikt zijn uiterste stand (B) bij x = 0,60 m.
Figuur 3 staat vergroot op de uitwerkbijlage.

figuur 3: (u,x)-diagram met op de verticale as de uitwijking u (in m, −0,20 tot 0,20) en op de horizontale as de afstand x (in m, 0 tot 0,70); een sinusachtige kromme vanuit u=−0,15 bij x=0 stijgend naar het maximum A bij x=0,50 (u=0,15) en weer dalend, met een rechte stippellijn van de oorsprong O naar punt A.$$, 'inline'),
  ('65af352a-960f-4601-adf8-7062f001bda9', '8f465511-2414-40b9-ad7c-c3de982225a6', $$uitwerkbijlage vraag 14 — figuur 3 vergroot, om punt B in te tekenen$$,
   $$natuurkunde-vwo-2016-i-vliegen-context6.png$$,
   $$uitwerkbijlage bij vraag 14: figuur 3 vergroot weergegeven ((u,x)-diagram van vogel 1 met punt O en punt A en de stippellijn OA), zodat de leerling hierin het punt B (uiterste vleugelstand van vogel 2, bij x = 0,60 m) kan intekenen.$$, 'uitwerkbijlage'),
  ('7ad80949-ec6f-4613-aff4-5bb25dc8a440', '8f465511-2414-40b9-ad7c-c3de982225a6', $$schaalfactor k en schaalwet ∝k^p; vliegsnelheid v∝√(m/A)$$,
   $$natuurkunde-vwo-2016-i-vliegen-context7.png$$,
   $$Als je een grote en een kleine vogel vergelijkt, nemen we aan dat van de grote vogel alle afstanden (lengte, breedte, hoogte en dus ook slaggrootte) k keer zo groot zijn als die van de kleine vogel. We spreken dan van schaalfactor k.
De drie grootheden f, d en v in formule (1) hangen van k af. Deze afhankelijkheid (schaalwet) geven we aan met:
…… ∝ k^p.
Hierin is:
− ∝ evenredig met;
− k schaalfactor;
− p een getal, afhankelijk van de betreffende grootheid.

De vliegsnelheid hangt alleen af van de massa m en de vleugeloppervlakte A van de vogel: v ∝ √(m/A).
De schaalwet voor de slagfrequentie luidt: f ∝ k^p.$$, 'inline'),
  ('17c2ede8-a269-4254-9b54-21e40cbc3421', '8f465511-2414-40b9-ad7c-c3de982225a6', $$uitwerkbijlage vraag 15 — zin over slagfrequentie bij 4× zo grote vogel$$,
   $$natuurkunde-vwo-2016-i-vliegen-context8.png$$,
   $$uitwerkbijlage bij vraag 15: de onvolledige zin “Als de lengte van de vogel 4 maal zo groot wordt, wordt de slagfrequentie f ……. maal zo …………... .”, zodat de leerling deze kan aanvullen.$$, 'uitwerkbijlage'),
  ('d134e72f-463f-43e4-99a0-312bd2104f8c', 'a6d0fa82-830f-4ba7-87b1-5bc985bb2c4a', $$HI-molecuul als massa-veersysteem (H trilt, I stilstaat), evenwichtsafstand 1,609·10⁻¹⁰ m$$,
   $$natuurkunde-vwo-2016-i-trillingen-binnen-een-molecuul-context1.png$$,
   $$Lees onderstaand artikel.

In het molecuul waterstofjodide (HI) is het kleine waterstofatoom gebonden aan het grote jodiumatoom. De evenwichtsafstand tussen de twee atomen is 1,609·10⁻¹⁰ m. Als deze afstand groter of kleiner wordt, zorgt de binding voor een terugdrijvende kracht die in eerste benadering recht evenredig is met de uitwijking van de evenwichtsstand.
Een model om het molecuul te beschrijven is een massa-veersysteem, waarbij het waterstofatoom trilt, het jodiumatoom stilstaat en de binding beschouwd wordt als een veer.
In het klassieke model van een harmonisch trillend systeem zijn alle energietoestanden mogelijk. Kijkt men echter naar het spectrum van waterstofjodide, dan blijkt dat geen continu spectrum maar een lijnenspectrum te zijn: om dat te begrijpen is een quantumfysisch model nodig!

figuur: schematische weergave van het I-atoom (stilstaand) en het H-atoom op evenwichtsafstand 0 daarvandaan.$$, 'inline'),
  ('2078918c-11e4-4170-96a2-57ef47ba551a', 'a6d0fa82-830f-4ba7-87b1-5bc985bb2c4a', $$figuur 1 — klassieke waarschijnlijkheidsverdeling P(u) van het trillende H-atoom, A=5,54·10⁻¹¹ m$$,
   $$natuurkunde-vwo-2016-i-trillingen-binnen-een-molecuul-context2.png$$,
   $$In figuur 1 is de klassieke waarschijnlijkheidsverdeling P(u) van het trillende H-atoom in het massa-veersysteem gegeven met amplitude A = 5,54·10⁻¹¹ m.

Uit de oppervlakte tussen twee posities onder de waarschijnlijkheidsverdeling is het percentage van de tijd te berekenen dat een trillende massa zich tussen die twee posities bevindt.

figuur 1: grafiek van de klassieke waarschijnlijkheidsverdeling P(u) tegen de uitwijking u (in pm, −60 tot 60); de kromme heeft een minimum bij u=0 en loopt naar boven divergerend naar u=−A en u=+A, met daaronder een schematische weergave van het I-atoom en het trillende H-atoom tussen de uiterste standen −A en +A rond evenwichtsstand 0.$$, 'inline'),
  ('961494d8-363d-44de-8072-6f4dfa1b99b0', 'a6d0fa82-830f-4ba7-87b1-5bc985bb2c4a', $$figuur 2 — lijnenspectrum van waterstofjodidegas met lijnen A, B en C$$,
   $$natuurkunde-vwo-2016-i-trillingen-binnen-een-molecuul-context3.png$$,
   $$Het spectrum van waterstofjodidegas is een lijnenspectrum. In dit spectrum zijn onder andere drie lijnen te zien. Zie figuur 2.

figuur 2: lijnenspectrum met op de horizontale as de frequentie f (in ·10¹⁴ Hz, 0,6 tot 2,2) en drie lijnen A (bij ongeveer 0,7·10¹⁴ Hz), B (bij ongeveer 1,4·10¹⁴ Hz) en C (bij ongeveer 2,05·10¹⁴ Hz), onderling ongeveer even ver uit elkaar.$$, 'inline'),
  ('3bf34256-fdf2-4b11-a3ea-b022b87504f0', 'a6d0fa82-830f-4ba7-87b1-5bc985bb2c4a', $$figuur 3 — energieniveauschema van HI met quantumgetallen n=0,1,2,3$$,
   $$natuurkunde-vwo-2016-i-trillingen-binnen-een-molecuul-context4.png$$,
   $$Dit lijnenspectrum is niet te verklaren met het klassieke model van het massa-veersysteem.
Blijkbaar heeft het HI-molecuul discrete energieniveaus.

Uit het spectrum van figuur 2 kan men het energie-niveau-schema van HI afleiden. Dit is in figuur 3 weergegeven. De energieniveaus worden aangegeven met de quantumgetallen n = 0, 1, 2, … . Figuur 3 staat ook op de uitwerkbijlage.

figuur 3: energieniveauschema met op de verticale as de energie E en vier horizontale niveaus, van onder naar boven aangeduid met n=0, n=1, n=2 en n=3, met onderling gelijke afstanden.$$, 'inline'),
  ('503d7f2b-28fc-425a-a376-29bf05bcf897', 'a6d0fa82-830f-4ba7-87b1-5bc985bb2c4a', $$uitwerkbijlage vraag 18 — figuur 3 (energieniveauschema n=0 t/m 3) om overgang B in te tekenen$$,
   $$natuurkunde-vwo-2016-i-trillingen-binnen-een-molecuul-context5.png$$,
   $$uitwerkbijlage bij vraag 18: figuur 3 (het energieniveauschema met n=0, 1, 2, 3) nogmaals weergegeven, zodat de leerling hierin met een pijl de overgang kan intekenen die hoort bij lijn B van figuur 2.$$, 'uitwerkbijlage'),
  ('e8dc2e77-04a9-45bd-984e-010c2fffe7bc', 'a6d0fa82-830f-4ba7-87b1-5bc985bb2c4a', $$quantumfysisch model: H-atoom als deeltje in één-dimensionale energieput$$,
   $$natuurkunde-vwo-2016-i-trillingen-binnen-een-molecuul-context6.png$$,
   $$Het is mogelijk om een quantumfysisch model van HI op te stellen, waarbij het trillende H-atoom beschreven wordt als een deeltje in een één-dimensionale energieput. De afstanden tussen de energieniveaus hangen af van de eigenschappen van de energieput.
We vergelijken de afstanden van de energieniveaus bij HI met de afstanden in twee andere quantumfysische modellen.$$, 'inline'),
  ('22ee104b-25fb-4450-879c-47ea5907018c', 'aa61f262-a657-4217-bad4-8a655ec2b54c', $$calcium-47 toegediend voor botonderzoek; vervalvergelijking ⁴⁷Ca→⁴⁷Sc+β⁻+γ$$,
   $$natuurkunde-vwo-2016-i-onderzoek-van-bot-met-calcium-47-context1.png$$,
   $$In deze opgave bekijken we een patiënt waarbij de botten in de benen worden onderzocht. Hierbij gebruikt men calcium omdat dit gemakkelijk door het lichaam opgenomen en getransporteerd wordt naar de botten.
De patiënt krijgt een hoeveelheid van de instabiele isotoop calcium-47 toegediend, die bij verval een bèta-min-deeltje en gammastraling uitzendt:
⁴⁷Ca → ⁴⁷Sc + β⁻ + γ.
De gammastraling kan buiten het lichaam gedetecteerd worden. De arts kan zo zien of er met de botten iets bijzonders aan de hand is.$$, 'inline'),
  ('0d0040c2-8021-4278-bfcf-9abacd3e3369', 'aa61f262-a657-4217-bad4-8a655ec2b54c', $$figuur 1 — apparaat met rijen gammadetectoren en loden plaat met openingen boven de benen$$,
   $$natuurkunde-vwo-2016-i-onderzoek-van-bot-met-calcium-47-context2.png$$,
   $$De benen van de patiënt worden onder een apparaat gelegd dat gammastraling meet. Zie figuur 1.

In het apparaat zijn honderden gammadetectoren in rijen naast elkaar geplaatst. Onder de gammadetectoren bevindt zich een dikke loden plaat. Onder elke gammadetector zit in de plaat een smal gat.

figuur 1: schematische tekening van de patiënt liggend op een tafel, met daarboven een loden plaat met smalle openingen, daarboven rijen gammadetectoren en een computer die het beeld op een monitor toont.$$, 'inline'),
  ('0bbc2a33-6458-403c-a15f-74c078466904', 'aa61f262-a657-4217-bad4-8a655ec2b54c', $$correctiefactor voor absorptie: 10 cm lucht + 4,5 cm spierweefsel, foton 1,0 MeV$$,
   $$natuurkunde-vwo-2016-i-onderzoek-van-bot-met-calcium-47-context3.png$$,
   $$Voor het maken van het beeld van het bot worden de gegevens door de computer verwerkt.
Voor verschillende delen van de benen verschilt de absorptie van gammastraling in het spierweefsel en in de lucht tussen de detector en het been.
Om de metingen van het been te kunnen vergelijken, moet voor die absorptie gecorrigeerd worden. Daarvoor vermenigvuldigt de computer de meetwaarde van elke detector met een correctiefactor.
Als er geen absorptie optreedt, levert dat een correctiefactor 1.
Neem aan dat zich tussen een gammadetector en het bot 10 cm lucht en 4,5 cm spierweefsel bevindt. De absorptie in spierweefsel is gelijk aan die in water. Ga uit van een gamma-foton met een energie van 1,0 MeV.$$, 'inline'),
  ('5c388c9e-7f20-4e3d-bd49-8b12a3a4c8c4', 'aa61f262-a657-4217-bad4-8a655ec2b54c', $$figuur 2 — gezamenlijke activiteit van calcium-47 en scandium-47 in het bot tegen de tijd$$,
   $$natuurkunde-vwo-2016-i-onderzoek-van-bot-met-calcium-47-context4.png$$,
   $$Een nadeel van deze onderzoeksmethode is de stralingsbelasting van het bot. Deze ontstaat voornamelijk door absorptie van bèta-min-deeltjes.
Deze zijn niet alleen afkomstig van calcium-47 maar ook van scandium-47 (dat ontstaat bij het verval van calcium-47).

Figuur 2 toont het verloop van de gezamenlijke activiteit van beide isotopen in het bot van het bovenbeen.

figuur 2: grafiek van de activiteit A (in Bq) tegen de tijd t (in dag, 0 tot 32); A stijgt eerst kort, bereikt al snel na t=0 een maximum en neemt daarna geleidelijk af, aanvankelijk vrijwel vlak en na ongeveer t=12 dagen steeds sneller dalend tot bijna 0 bij t=32.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('bb1d9800-1bb1-42a2-bfc2-8ce3e0c0e948', '881307d4-97f4-4979-ad9d-f9eb03d851ab', 1,
   $$[{"domain": "Lading en veld", "subdomain": "Elektrische systemen"}]$$::jsonb,
   $$["diode in doorlaatrichting", "spanningsdeling in een serieschakeling", "(U,I)-diagram aflezen", "wet van Ohm"]$$::jsonb,
