   $$natuurkunde-vwo-2016-i-gekleurde-leds-vraag1.png$$, $$Bepaal de grootte van de weerstand R.$$, array['1b336385-f4d1-4f4c-af28-d632ba3ce90c','e6236d9e-f770-47b7-bc68-54503f0acda3']::uuid[]),
  ('15179cb3-8eb8-48bb-bef5-ed1c76f6b9be', '881307d4-97f4-4979-ad9d-f9eb03d851ab', 2,
   $$[{"domain": "Lading en veld", "subdomain": "Elektrische systemen"}]$$::jsonb,
   $$["(U,I)-karakteristiek vergelijken", "spanningsdeling", "serieschakeling", "diodespanning"]$$::jsonb,
